const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function safe(value, fallback = null) {
  return value === undefined || value === null || value === "" ? fallback : value;
}

function makeReviewId(eventId) {
  const base = eventId || "unknown_event";
  const suffix = Date.now().toString(36);
  return `review_${base}_${suffix}`.replace(/[^a-zA-Z0-9_]/g, "_");
}

function inferReviewReason(source, config) {
  if (config.review_reason) return config.review_reason;
  if (source.dedupe?.decision === "possible_duplicate") return "Possible duplicate detected";
  if (source.suppression?.decision === "manual_review") return "Suppression or consent requires manual review";
  if (source.approval?.status === "pending") return "Approval pending";
  if (source.error_log?.status === "logged") return "Workflow error requires review";
  if (source.routing?.status === "fallback") return "Fallback route requires manual review";
  return "Manual review required";
}

function inferQueueType(source, config) {
  if (config.queue_type) return config.queue_type;
  if (source.dedupe?.decision === "possible_duplicate") return "dedupe_review";
  if (source.suppression?.decision === "manual_review") return "consent_review";
  if (source.approval?.status === "pending") return "approval_review";
  if (source.error_log?.status === "logged") return "error_retry_review";
  if (source.routing?.status === "fallback") return "routing_review";
  return "manual_review";
}

function inferPriority(source, config) {
  return config.priority || source.error_log?.severity || source.priority || "normal";
}

function inferAllowedActions(source, config) {
  if (Array.isArray(config.allowed_actions) && config.allowed_actions.length > 0) {
    return config.allowed_actions;
  }
  if (Array.isArray(source.approval?.allowed_actions)) return source.approval.allowed_actions;
  if (source.dedupe?.decision === "possible_duplicate") return ["approve_create", "merge_update", "reject"];
  if (source.suppression?.decision === "manual_review") return ["mark_consented", "mark_do_not_contact", "request_clarification"];
  if (source.error_log?.status === "logged") return ["retry_ready", "resolved", "ignore"];
  return ["approve", "reject", "revise"];
}

function extractContext(source) {
  return {
    dedupe: source.dedupe || null,
    suppression: source.suppression || null,
    approval: source.approval || null,
    error_log: source.error_log || null,
    routing: source.routing || null,
    payload: source.payload || source.source_result?.payload || null
  };
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C5-E",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        review_queue_item: null,
        notification_payload: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C5-E will not create manual review item when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

const reviewTriggers = ["manual_review", "notify_reviewer", "notify_error_owner"];
if (!reviewTriggers.includes(source.next_action)) {
  return fail({
    code: "REVIEW_NOT_REQUESTED",
    message: "source.next_action does not require manual review.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.reviewer_email && !source.approval?.reviewer_email && !source.error_log?.owner_email) {
  return fail({
    code: "MISSING_REVIEWER_EMAIL",
    message: "reviewer email is required from config, approval, or error owner."
  });
}

const createdAt = nowIso();
const reviewId = makeReviewId(source.event_id);
const queueType = inferQueueType(source, config);
const reviewReason = inferReviewReason(source, config);
const reviewerEmail = config.reviewer_email || source.approval?.reviewer_email || source.error_log?.owner_email;
const allowedActions = inferAllowedActions(source, config);

const reviewQueueItem = {
  review_id: reviewId,
  queue_type: queueType,
  review_status: "open",
  review_reason: reviewReason,
  event_id: source.event_id || null,
  event_type: source.event_type || null,
  source_component: source.component_id || null,
  source_component_version: source.component_version || null,
  owner: config.owner || source.owner || "unassigned",
  reviewer_email: reviewerEmail,
  priority: inferPriority(source, config),
  allowed_actions: allowedActions,
  context: extractContext(source),
  decision: null,
  reviewer_notes: "",
  created_at: createdAt,
  updated_at: createdAt
};

const text = [
  `Manual review required`,
  ``,
  `Review ID: ${reviewId}`,
  `Queue Type: ${queueType}`,
  `Reason: ${reviewReason}`,
  `Event ID: ${safe(source.event_id, "-")}`,
  `Event Type: ${safe(source.event_type, "-")}`,
  `Source Component: ${safe(source.component_id, "-")}`,
  `Priority: ${reviewQueueItem.priority}`,
  `Allowed Actions: ${allowedActions.join(", ")}`
].join("\n");

return [
  {
    json: {
      success: true,
      component_id: "C5-E",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      review_queue_item: reviewQueueItem,
      notification_payload: {
        channel: "email",
        to: reviewerEmail,
        subject: `Manual review required: ${reviewReason}`,
        text
      },
      source_result: source,
      error: null,
      next_action: config.default_next_action || "notify_reviewer"
    }
  }
];
